 "content": "def transform(grid):
    """Recolor large repeated rectangular runs with color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    runs = {}
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            end = c + 1
            while end < w and row[end] == row[c]:
                end += 1
            if end - c >= 5:
                key = (row[c], c, end)
                runs.setdefault(key, []).append(r)
            c = end
    for (color, left, right), rows in runs.items():
        # Split rows into contiguous same-width runs, retaining the first
        # six rows of each large rectangular patch.
        groups = []
        for r in rows:
            if not groups or r != groups[-1][-1] + 1:
                groups.append([r])
            else:
                groups[-1].append(r)
        for group in groups:
            if len(group) >= 5:
                for r in group[:6]:
                    for c in range(left, right):
                        out[r][c] = 4
    return out
